{
  "purpose": "This repository contains Andrew Dryga’s GitHub profile and dryga.com, a personal portfolio and engineering blog for readers, collaborators, and prospective clients. The website uses Astro 6, TypeScript, Tailwind CSS, and MDX, with a terminal-inspired component library and a Cloudflare Worker for contact email and analytics proxying.",
  "components": [
    {
      "path": "README.md",
      "what_it_does": "GitHub profile with career highlights, selected writing, and contact links."
    },
    {
      "path": "src",
      "what_it_does": "Active website source; the application’s package and build configuration are at the repository root."
    },
    {
      "path": "src/pages",
      "what_it_does": "Astro routes for the homepage, blog, projects, tags, component library, feeds, robots, and 404 page."
    },
    {
      "path": "src/content",
      "what_it_does": "MDX collections for blog posts, project details, and testimonials."
    },
    {
      "path": "src/content.config.ts",
      "what_it_does": "Collection loaders and validation schemas, including required blog categories and project IDs."
    },
    {
      "path": "src/components",
      "what_it_does": "Shared layouts, navigation, terminal components, UI primitives, and MDX diagram components."
    },
    {
      "path": "src/component-library",
      "what_it_does": "Reusable previews for the component documentation pages."
    },
    {
      "path": "src/data",
      "what_it_does": "Project metadata, technology lists, testimonial loading, and component library navigation."
    },
    {
      "path": "src/lib/blog.ts",
      "what_it_does": "Loads blog entries, excludes production drafts, and builds sorted summaries and categories."
    },
    {
      "path": "src/scripts",
      "what_it_does": "Browser behavior for navigation and Mixpanel analytics."
    },
    {
      "path": "src/utils/shortcuts.ts",
      "what_it_does": "Shared keyboard shortcut handling."
    },
    {
      "path": "src/styles/global.css",
      "what_it_does": "Global styles, semantic design tokens, fonts, and reduced-motion handling."
    },
    {
      "path": "public",
      "what_it_does": "Static fonts, images, icons, downloadable CV, LLM index, and HTTP header rules."
    },
    {
      "path": "scripts",
      "what_it_does": "Utilities for full-site text exports, icon generation, and the component library smoke check."
    },
    {
      "path": "worker/index.ts",
      "what_it_does": "Serves static assets, sends contact email through Resend, proxies Mixpanel requests, and redirects the sitemap URL."
    },
    {
      "path": "wrangler.jsonc",
      "what_it_does": "Configures the Cloudflare Worker entry point and binds dist as static assets."
    },
    {
      "path": "astro.config.mjs",
      "what_it_does": "Sets the site URL, MDX, sitemap, critical CSS integration, prefetching, and syntax highlighting."
    },
    {
      "path": "tailwind.config.ts",
      "what_it_does": "Defines the shared Tailwind theme and animation configuration."
    },
    {
      "path": ".github/workflows/ci.yml",
      "what_it_does": "Runs dependency installation, Astro checks, TypeScript checks, and a build on pull requests and main pushes."
    },
    {
      "path": "astro",
      "what_it_does": "Contains tracked generated Astro metadata rather than a separate application."
    }
  ],
  "build_test_run": [
    {
      "command": "npm ci",
      "source_file": ".github/workflows/ci.yml",
      "what_it_does": "Installs locked dependencies from the repository root; CI uses Node.js 22."
    },
    {
      "command": "npm run dev",
      "source_file": "package.json",
      "what_it_does": "Starts Astro development, normally on port 4321; predev generates a missing public text export using a .llms-cache build."
    },
    {
      "command": "npm run build",
      "source_file": "package.json",
      "what_it_does": "Builds the static site into dist and refreshes llms-full.txt in dist and public."
    },
    {
      "command": "npm run preview",
      "source_file": "package.json",
      "what_it_does": "Previews the Astro build locally; this does not start the Cloudflare Worker."
    },
    {
      "command": "npm run check",
      "source_file": "package.json",
      "what_it_does": "Runs Astro diagnostics; required by CI."
    },
    {
      "command": "npm run typecheck",
      "source_file": "package.json",
      "what_it_does": "Runs TypeScript without emitting files; required by CI, but the configured include paths omit worker."
    },
    {
      "command": "npm run lint",
      "source_file": "package.json",
      "what_it_does": "Runs ESLint with the root Astro and TypeScript configuration; not included in CI."
    },
    {
      "command": "npm run format",
      "source_file": "package.json",
      "what_it_does": "Formats files in place with Prettier."
    },
    {
      "command": "npm run smoke:component-library",
      "source_file": "package.json",
      "what_it_does": "Starts development on port 43210 and checks that /component-library/ responds successfully with its expected heading."
    },
    {
      "command": "npm run generate:llms-full",
      "source_file": "package.json",
      "what_it_does": "Exports existing dist HTML to plain text; skips when all export targets exist unless LLMS_FORCE_REBUILD is true."
    }
  ],
  "deploy_release": [
    {
      "source_file": ".github/workflows/ci.yml",
      "step": "Pull requests and pushes to main run checks and build under Node.js 22. This workflow contains no deployment step."
    },
    {
      "source_file": "src/README.md",
      "step": "The older deployment guide describes Cloudflare Pages with npm run build and dist as output, plus PUBLIC_MIXPANEL_TOKEN in the deployment environment."
    },
    {
      "source_file": "wrangler.jsonc",
      "step": "Current configuration defines a Worker named andrewdryga using worker/index.ts and the dist directory through the ASSETS binding; the deployment trigger is not defined here."
    },
    {
      "source_file": "worker/index.ts",
      "step": "The deployed contact endpoint requires RESEND_API_KEY to send email through Resend; provisioning instructions are absent."
    }
  ],
  "conventions": [
    {
      "rule": "Reuse existing UI components and Button variants; document new patterns in the component library.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Use semantic HSL color tokens, terminal-style borders, and the Tailwind 4px spacing scale.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Use monospace for technical content and buttons, and sans-serif for prose and headings.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep animations in the shared Tailwind configuration, use short transitions, and respect reduced motion.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Preserve keyboard access and focus rings, label controls, associate form help and errors, and maintain at least 7:1 text contrast.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Validate responsive layouts from sm through xl; provide hover and focus states for interactive elements.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Use terse developer-oriented labels and error messages without exclamation marks or decorative emojis.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep analytics within the existing Mixpanel setup and its Do Not Track guard.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Name components in PascalCase; place shared utilities in src/lib or src/utils with camelCase exports.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Keep Astro script tags at template top level; move complex logic into shared helpers.",
      "source_file": "AGENTS.md"
    },
    {
      "rule": "Use shortcut buttons only for commands actually wired through the shared shortcut utility.",
      "source_file": "AGENTS.md"
    }
  ],
  "where_to_look": [
    {
      "task": "Change homepage content or the contact form",
      "path": "src/pages/index.astro"
    },
    {
      "task": "Write or edit a blog post",
      "path": "src/content/blog"
    },
    {
      "task": "Check required MDX frontmatter",
      "path": "src/content.config.ts"
    },
    {
      "task": "Change project metadata and listing visibility",
      "path": "src/data/projects.ts"
    },
    {
      "task": "Add project detail prose with a matching projectId",
      "path": "src/content/projects"
    },
    {
      "task": "Add or reorder testimonials",
      "path": "src/content/testimonials"
    },
    {
      "task": "Find reusable UI primitives",
      "path": "src/components/ui"
    },
    {
      "task": "Document or inspect design patterns",
      "path": "src/pages/component-library"
    },
    {
      "task": "Add diagrams to MDX content",
      "path": "src/components/mdx/SequenceDiagram"
    },
    {
      "task": "Change global metadata, canonical URLs, or font loading",
      "path": "src/components/BaseLayout.astro"
    },
    {
      "task": "Change analytics behavior or session replay sampling",
      "path": "src/scripts/mixpanel.ts"
    },
    {
      "task": "Change contact delivery or analytics proxying",
      "path": "worker/index.ts"
    },
    {
      "task": "Change security headers or caching rules",
      "path": "public/_headers"
    },
    {
      "task": "Change the generated full-site text export",
      "path": "scripts/generate-llms-full.mjs"
    }
  ],
  "open_questions": [
    "Is production deployed through Cloudflare Workers or the older documented Pages setup, and who owns the deployment trigger and verification steps?",
    "How should contributors provision RESEND_API_KEY and run the Worker locally to verify contact email and the analytics proxy?",
    "What validation is expected beyond CI and the component library smoke check? No npm test script exists, and the Worker is outside the current TypeScript check."
  ]
}
